head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods70006_r0i0";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — registerMode, registYn, param.method

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods70006_r0i0.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_registerMode", fn: function(){ return ((dma_pageContext.get("registerMode") ?? "") === '1'); } }, { id: "if_registerMode_2", fn: function(){ return ((dma_pageContext.get("registerMode") ?? "") === '2'); } }, { id: "if_registerMode", fn: function(){ return ((dma_pageContext.get("registYn") ?? "") === 'Y'); } }, { id: "if_registerMode_2", fn: function(){ return ((dma_pageContext.get("registYn") ?? "") === 'Y'); } }, { id: "if_registYn_2", fn: function(){ return ((dma_pageContext.get("registYn") ?? "") === 'N'); } }, { id: "if_registerMode", fn: function(){ return ((dma_pageContext.get("method") ?? "") === 'registerAttachFile'); } }, { id: "if_registerMode_2", fn: function(){ return ((dma_pageContext.get("method") ?? "") === 'registerAttachFile'); } }, { id: "if_registYn_2", fn: function(){ return ((dma_pageContext.get("method") ?? "") === 'registerAttachFile'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("errorCd") ?? ""))); } },
        { childId: "__rb2", fn: function () { return String(String((dma_pageContext.get("errorCd") ?? ""))); } },
        { childId: "__rb4", fn: function () { return String(String((dma_pageContext.get("errorCd") ?? ""))); } },
        { childId: "__rb5", fn: function () { return " { \"messageStr\":\"" + String(String((dma_pageContext.get("messageStr") ?? ""))) + "\" } "; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };
